-- Generated by `pnpm decisions:seed` from docs/planning/decisions.md (decision 191): the log's
-- entries as decisions, numbered as in the log, active unless a later entry replaces them.
-- Do not edit by hand.
insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (208, 'How slice 3.2 is built (`slice-3-2.md`), from G12 and rule 11. A decision recorded to replace an active decision someone else made is always proposed, and only its deciders may confirm or reword it: the owner of the replaced decision''s area if they owned it then, else the fallback, and the person who made the replaced decision. Whoever could act on it before may still reject it. Deciders are fixed when it is recorded. A conflict is kept for each such proposal and for each the teammate raises with a new `raise_conflict` tool (positions, the decisions it bears on, the area), posted in the thread with the deciders mentioned, at most three open per thread, and settled by a decider in the web app (`kept`, `changed`, `dismissed`) or by acting on its proposal. Capture flags a proposal that replaces an active decision the same way, posting nothing (176). No model runs to find conflicts', 'The latest message must not win by default (rule 11). Fixing the deciders at recording keeps one rule wherever a person presses and stops a later change of owner taking over what waits. Letting anyone withdraw a proposal keeps the record from filling with stuck ones, since withdrawing changes nothing', 'active', 'the owner', '2026-11-25T00:00:00Z', 'import', '208')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
